 "content": "from math import gcd

def transform(grid):
    out = [row[:] for row in grid]
    n = min(len(out), len(out[0]) if out else 0)
    pts = [(r, c) for r in range(n) for c in range(n) if out[r][c] == 1 and r == c]
    if len(pts) < 2:
        return out
    inds = sorted(r for r, _ in pts)
    step = 0
    for a, b in zip(inds, inds[1:]):
        step = gcd(step, b - a)
    if step <= 0:
        return out
    k = inds[-1] + step
    while k < n:
        if out[k][k] == 0:
            out[k][k] = 2
        k += step
    return out
